package com.medicine.reminder.service;
import com.medicine.reminder.dto.MedicineDTO; import com.medicine.reminder.model.*; import com.medicine.reminder.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class MedicineService {private final MedicineRepository meds;private final ProfileRepository profiles;public MedicineService(MedicineRepository m,ProfileRepository p){meds=m;profiles=p;}
 public List<Medicine> list(Long profileId,Long uid){profile(profileId,uid);return meds.findByProfileId(profileId);} public Medicine create(MedicineDTO d,Long uid){Medicine m=new Medicine();copy(m,d);m.setProfile(profile(d.getProfileId(),uid));return meds.save(m);} public Medicine update(Long id,MedicineDTO d,Long uid){Medicine m=owned(id,uid);copy(m,d);if(!m.getProfile().getId().equals(d.getProfileId()))m.setProfile(profile(d.getProfileId(),uid));return meds.save(m);} public void delete(Long id,Long uid){meds.delete(owned(id,uid));}
 public Medicine refillStock(Long id,int quantity,Long uid){if(quantity<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Refill quantity must be at least one");Medicine m=owned(id,uid);m.setStock((m.getStock()==null?0:m.getStock())+quantity);return meds.save(m);} public void decrementStock(Long id){meds.findById(id).ifPresent(m->{m.setStock(Math.max(0,(m.getStock()==null?0:m.getStock())-1));meds.save(m);});}
 private void copy(Medicine m,MedicineDTO d){m.setName(d.getName().trim());m.setDosage(d.getDosage().trim());m.setDescription(d.getDescription());m.setColor(d.getColor()==null||d.getColor().isBlank()?"#4CAF50":d.getColor());if(d.getStock()!=null)m.setStock(d.getStock());if(d.getLowStockThreshold()!=null)m.setLowStockThreshold(d.getLowStockThreshold());} private Medicine owned(Long id,Long u){return meds.findByIdAndProfileUserId(id,u).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Medicine not found"));} private UserProfile profile(Long id,Long u){return profiles.findByIdAndUserId(id,u).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile not found"));}
}
